    31  static void ndpi_search_iec60870_tcp(struct ndpi_detection_module_struct *ndpi_struct,
    32                                       struct ndpi_flow_struct *flow) {
    33    struct ndpi_packet_struct *packet = &ndpi_struct->packet;
    34
    35    /* Check connection over TCP */
    36    NDPI_LOG_DBG(ndpi_struct, "search IEC60870\n");
    37
    38    if(packet->tcp) {
    39      u_int16_t offset = 0, found = 0;
    40
    41      while(offset + 1 < packet->payload_packet_len) {
    42        /* The start byte of 104 is 0x68 */
    43        if(packet->payload[offset] == 0x68) {
    44          u_int8_t len = packet->payload[offset+1];
    45
    46          if(len == 0)
    47            break;
    48          else {
    49            u_int8_t len = packet->payload[offset+1];
    50
    51            if((len + offset + 2) == packet->payload_packet_len) {
    52              found = 1;
    53              break;
    54            }
    55
    56            offset += len + 2;
    57          }
    58        } else
    59          break;
    60      }
    61
    62      if(found) {
    63        NDPI_LOG_INFO(ndpi_struct, "Found IEC60870-104\n");
    64
    65        ndpi_set_detected_protocol(ndpi_struct, flow, NDPI_PROTOCOL_IEC60870, NDPI_PROTOCOL_UNKNOWN, NDPI_CONFIDENCE_DPI);
    66        return;
    67      }
    68    }
    69
    70    NDPI_EXCLUDE_PROTO(ndpi_struct, flow);
    71  }
